mapper.select:
SELECT DISTINCT city FROM property_listing WHERE status = 'ACTIVE' AND city IS NOT NULL AND city != ''
AND prefecture = #{prefecture}
ORDER BY city


AND p.prefecture = #{prefecture}
AND p.city = #{city}
AND p.layout = #{layout}
AND p.rent_yen >= #{minRent}
AND p.rent_yen <= #{maxRent}
AND p.walk_minutes <= #{walkMinutes}
AND p.source_id = #{sourceId}




      AND (STRPOS(p.title, #{queryKeyword}) > 0 OR STRPOS(p.address, #{queryKeyword}) > 0
        OR STRPOS(p.station_name, #{queryKeyword}) > 0 OR STRPOS(s.source_name, #{queryKeyword}) > 0)


      AND (LOCATE(#{queryKeyword}, p.title) > 0 OR LOCATE(#{queryKeyword}, p.address) > 0
        OR LOCATE(#{queryKeyword}, p.station_name) > 0 OR LOCATE(#{queryKeyword}, s.source_name) > 0)




  ORDER BY p.rent_yen IS NULL, p.rent_yen, p.id DESC
  ORDER BY p.walk_minutes IS NULL, p.walk_minutes, p.id DESC
  ORDER BY p.created_at DESC, p.id DESC

LIMIT 120
